# Exact dominance queries with O(V+E) transient memory rather than one
# near-full block set for every block. Query results alone are cached.
successors={label:set() for label in blocks}
for target,parents in pred.items():
    for parent in parents:successors[parent].add(target)
def can_reach(target,removed=None):
    assert target in blocks and (removed is None or removed in blocks)
    if entry==removed or target==removed:return False
    pending=[entry];seen={entry}
    while pending:
        current=pending.pop()
        if current==target:return True
        for nxt in successors[current]:
            if nxt!=removed and nxt not in seen:
                seen.add(nxt);pending.append(nxt)
    return False
reachable_queries={};dominance_queries={}
def reachable(target):
    if target not in reachable_queries:reachable_queries[target]=can_reach(target)
    return reachable_queries[target]
def dominates(dominator,target):
    assert reachable(dominator) and reachable(target)
    key=(dominator,target)
    if key not in dominance_queries:
        dominance_queries[key]=(dominator==entry or dominator==target or not can_reach(target,dominator))
    return dominance_queries[key]

